<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free URL Encoder & Decoder Online','description'=>'Encode or decode URL text safely in your browser.','url'=>'https://smarttoolz.in/tools/url-encoder/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">URL ENCODER</span><h1>URL Encoder & Decoder</h1><p>Convert URLs and query text between encoded and readable forms.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Input<textarea id="in" rows="10" placeholder="https://example.com/search?q=hello world"></textarea></label><div style="display:flex;gap:10px;flex-wrap:wrap"><button id="e" class="tool-btn">Encode URL</button><button id="d" class="tool-btn">Decode URL</button></div><textarea id="out" rows="10" readonly style="margin-top:15px;width:100%;box-sizing:border-box"></textarea><button id="copy" class="tool-btn" style="margin-top:10px">Copy</button></div></section></main><script>(()=>{const i=document.getElementById('in'),o=document.getElementById('out');document.getElementById('e').onclick=()=>o.value=encodeURIComponent(i.value);document.getElementById('d').onclick=()=>{try{o.value=decodeURIComponent(i.value)}catch{o.value='Invalid encoded URL.'}};document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(o.value)})();</script><?php smarttoolz_tool_page_end(); ?>